        "املأ نقطة البداية من موقعي الحالي (GPS) بضغطة واحدة": { en: "Fill the start point from my current location (GPS) in one tap", fr: "Remplir le départ depuis ma position (GPS) en un geste", de: "Startpunkt per GPS an einem Tipp ausfüllen", es: "Rellenar el inicio con mi ubicación (GPS) de un toque", pt: "Preencher a partida com a minha localização (GPS) num toque", it: "Compila la partenza con la mia posizione (GPS) con un tocco" },
        "استخدم موقعي الحالي كنقطة بداية": { en: "Use my current location as the start point", fr: "Utiliser ma position comme point de départ", de: "Meinen Standort als Startpunkt verwenden", es: "Usar mi ubicación como punto de partida", pt: "Usar a minha localização como partida", it: "Usa la mia posizione come partenza" },
