        "احتمال تجمّد/صقيع": { en: "Possible icing/frost", fr: "Risque de verglas/gel", de: "Mögliches Glatteis/Frost", es: "Posible helada/hielo", pt: "Possível gelo/geada", it: "Possibile ghiaccio/gelo" },
        "حرارة إجهاد للمحرك والسائق": { en: "Engine and driver heat stress", fr: "Chaleur éprouvante pour moteur et conducteur", de: "Hitzebelastung für Motor und Fahrer", es: "Calor agotador para motor y conductor", pt: "Calor esgotante para o motor e o condutor", it: "Calura per motore e conducente" },
        "نحدد اسم النقطة الجديدة…": { en: "Looking up the new point's name…", fr: "Recherche du nom du nouveau point…", de: "Name des neuen Punkts wird gesucht…", es: "Buscando el nombre del nuevo punto…", pt: "A procurar o nome do novo ponto…", it: "Ricerca del nome del nuovo punto…" },
        "تم إسقاط الدبوس · نستخرج اسم الموقع…": { en: "Pin dropped · fetching the place name…", fr: "Épingle posée · récupération du nom du lieu…", de: "Pin gesetzt · Ortsname wird ermittelt…", es: "Pin colocado · obteniendo el nombre del lugar…", pt: "Pin colocado · a obter o nome do local…", it: "Pin posizionato · recupero del nome del luogo…" },
        "النقطتان جاهزتان · نرسم الطريق تلقائيًا…": { en: "Both points ready · drawing the route automatically…", fr: "Les deux points sont prêts · tracé automatique de l'itinéraire…", de: "Beide Punkte bereit · Route wird automatisch gezeichnet…", es: "Ambos puntos listos · dibujando la ruta automáticamente…", pt: "Ambos os pontos prontos · a desenhar a rota automaticamente…", it: "Entrambi i punti pronti · tracciamento automatico del percorso…" },
        "تم تحديد {w} · أكمل النقطة الأخرى لرسم الطريق تلقائيًا.": { en: "{w} set · complete the other point to draw the route automatically.", fr: "{w} définie · complétez l'autre point pour tracer l'itinéraire automatiquement.", de: "{w} gesetzt · ergänze den anderen Punkt, um die Route automatisch zu zeichnen.", es: "{w} definido · completa el otro punto para dibujar la ruta automáticamente.", pt: "{w} definido · complete o outro ponto para desenhar a rota automaticamente.", it: "{w} impostato · completa l'altro punto per tracciare automaticamente il percorso." },
        "نرسم المسار على الشبكة الطرقية…": { en: "Drawing the route on the road network…", fr: "Tracé de l'itinéraire sur le réseau routier…", de: "Route wird im Straßennetz gezeichnet…", es: "Dibujando la ruta en la red viaria…", pt: "A desenhar a rota na rede rodoviária…", it: "Tracciamento del percorso sulla rete stradale…" },
        "نفحص طقس نقاط الطريق حسب وقت الوصول المتوقع…": { en: "Checking weather at route points by expected arrival time…", fr: "Vérification de la météo aux points selon l'heure d'arrivée prévue…", de: "Wetter an den Routenpunkten nach Ankunftszeit wird geprüft…", es: "Comprobando el tiempo en los puntos según la llegada prevista…", pt: "A verificar o tempo nos pontos conforme a chegada prevista…", it: "Verifica del meteo nei punti secondo l'arrivo previsto…" },
        "لم نجد طريقًا بريديًا بين النقطتين.": { en: "No road route found between the two points.", fr: "Aucun itinéraire routier entre les deux points.", de: "Keine Straßenroute zwischen den beiden Punkten gefunden.", es: "No se encontró ruta por carretera entre los dos puntos.", pt: "Nenhuma rota rodoviária entre os dois pontos.", it: "Nessun percorso stradale tra i due punti." },
        "تعذّر جلب طقس نقاط الطريق. حاول مجددًا.": { en: "Could not fetch weather for route points. Try again.", fr: "Impossible d'obtenir la météo des points. Réessayez.", de: "Wetter der Routenpunkte konnte nicht geladen werden. Erneut versuchen.", es: "No se pudo obtener el tiempo de los puntos. Reintenta.", pt: "Não foi possível obter o tempo dos pontos. Tente novamente.", it: "Impossibile ottenere il meteo dei punti. Riprova." },
        "جارٍ التحليل…": { en: "Analyzing…", fr: "Analyse en cours…", de: "Analyse läuft…", es: "Analizando…", pt: "A analisar…", it: "Analisi in corso…" },
        "تعذّر إكمال فحص الطريق الآن. حاول مجددًا بعد قليل.": { en: "Could not complete the route check now. Try again shortly.", fr: "Impossible de terminer la vérification maintenant. Réessayez dans un instant.", de: "Routenprüfung jetzt nicht möglich. Versuche es gleich erneut.", es: "No se pudo completar la comprobación. Reintenta en un momento.", pt: "Não foi possível concluir a verificação. Tente novamente em breve.", it: "Impossibile completare la verifica ora. Riprova tra poco." },
        "أدخل نقطة البداية أولًا.": { en: "Enter the start point first.", fr: "Saisissez d'abord le point de départ.", de: "Gib zuerst den Startpunkt ein.", es: "Introduce primero el punto de partida.", pt: "Introduza primeiro o ponto de partida.", it: "Inserisci prima il punto di partenza." },
        "أدخل نقطة النهاية أولًا.": { en: "Enter the destination first.", fr: "Saisissez d'abord la destination.", de: "Gib zuerst das Ziel ein.", es: "Introduce primero el destino.", pt: "Introduza primeiro o destino.", it: "Inserisci prima la destinazione." },
        "لم نتعرف على «{q}». جرّب اسمًا أوضح أو حدد النقطة من الخريطة 📍": { en: "We could not recognize \"{q}\". Try a clearer name or pick the point on the map 📍", fr: "Nous n'avons pas reconnu « {q} ». Essayez un nom plus clair ou choisissez le point sur la carte 📍", de: "„{q}\" wurde nicht erkannt. Versuche einen klareren Namen oder wähle den Punkt auf der Karte 📍", es: "No reconocimos «{q}». Prueba un nombre más claro o marca el punto en el mapa 📍", pt: "Não reconhecemos «{q}». Tente um nome mais claro ou marque o ponto no mapa 📍", it: "Non abbiamo riconosciuto «{q}». Prova un nome più chiaro o scegli il punto sulla mappa 📍" },
        "لا نتائج مطابقة داخل مصر — جرّب اسمًا أوضح أو حدد من الخريطة 📍": { en: "No matching results in Egypt — try a clearer name or pick from the map 📍", fr: "Aucun résultat correspondant en Égypte — essayez un nom plus clair ou choisissez sur la carte 📍", de: "Keine Treffer in Ägypten — klareren Namen versuchen oder auf der Karte wählen 📍", es: "Sin resultados en Egipto — prueba un nombre más claro o marca en el mapa 📍", pt: "Sem resultados no Egito — tente um nome mais claro ou marque no mapa 📍", it: "Nessun risultato in Egitto — prova un nome più chiaro o scegli sulla mappa 📍" },
