        "يقرأ طقس يومك الآن…": { en: "Reading your day's weather now…", fr: "Lecture de la météo de votre journée…", de: "Das Wetter Ihres Tages wird gelesen…", es: "Leyendo el clima de tu día…", pt: "A ler o clima do seu dia…", it: "Lettura del meteo della tua giornata…" },
        "تحليل تلقائي يُولَّد على جهازك من توقعات موقعك — استرشادي ولا يُغني عن متابعة التحديثات الرسمية.": { en: "Automatic analysis generated on your device from your location's forecasts — indicative, and no substitute for official updates.", fr: "Analyse automatique générée sur votre appareil à partir des prévisions de votre position — indicative, sans remplacer les bulletins officiels.", de: "Automatische Analyse auf Ihrem Gerät aus den Vorhersagen Ihres Ortes — Richtwert, ersetzt keine offiziellen Warnungen.", es: "Análisis automático generado en su dispositivo a partir de las previsiones de su ubicación: orientativo, no sustituye a los avisos oficiales.", pt: "Análise automática gerada no seu dispositivo a partir das previsões da sua localização — indicativa, não substitui os avisos oficiais.", it: "Analisi automatica generata sul tuo dispositivo dalle previsioni della tua posizione — indicativa, non sostituye gli avvisi ufficiali." },
        "يحلّل توقعات اليوم والأسبوع…": { en: "Analyzing today's and the week's forecast…", fr: "Analyse des prévisions du jour et de la semaine…", de: "Vorhersagen für heute und die Woche werden analysiert…", es: "Analizando las previsiones de hoy y de la semana…", pt: "A analisar as previsões de hoje e da semana…", it: "Analisi delle previsioni di oggi e della settimana…" },
        "المستشار الذكي للأشهر القادمة": { en: "Smart advisor for the months ahead", fr: "Conseiller intelligent pour les mois à venir", de: "Intelligenter Berater für die kommenden Monate", es: "Asesor inteligente para los próximos meses", pt: "Consultor inteligente para os próximos meses", it: "Consulente intelligente per i mesi a venire" },
        "قراءة شبيهة بالبشر لتوجهات SEAS5 وتوقعات الشهر القادم": { en: "A human-like read of SEAS5 trends and next month's outlook", fr: "Une lecture humaine des tendances SEAS5 et du mois prochain", de: "Eine menschennahe Auswertung der SEAS5-Trends und des nächsten Monats", es: "Una lectura cercana de las tendencias SEAS5 y del próximo mes", pt: "Uma leitura humana das tendências SEAS5 e do próximo mês", it: "Una lettura umana delle tendenze SEAS5 e del prossimo mese" },
        "يقرأ توجه الأشهر القادمة الآن…": { en: "Reading the months-ahead outlook now…", fr: "Lecture des tendances des mois à venir…", de: "Trend der kommenden Monate wird gelesen…", es: "Leyendo la tendencia de los próximos meses…", pt: "A ler a tendência dos próximos meses…", it: "Lettura della tendenza dei prossimi mesi…" },
        "تحليل تلقائي من أرقام SEAS5 ومناخ العقد على جهازك — استرشادي للتخطيط الموسمي.": { en: "Automatic analysis from SEAS5 and the decade climate on your device — indicative for seasonal planning.", fr: "Analyse automatique à partir des chiffres SEAS5 et du climat décennal sur votre appareil — indicative pour la planification saisonnière.", de: "Automatische Analyse aus SEAS5-Zahlen und dem Dekadenklima auf Ihrem Gerät — Richtwert für die Saisonplanung.", es: "Análisis automático a partir de los datos SEAS5 y del clima decenal en su dispositivo: orientativo para la planificación estacional.", pt: "Análise automática a partir dos números SEAS5 e do clima decenal no seu dispositivo — indicativa para o planeamento sazonal.", it: "Analisi automatica dai dati SEAS5 e dal clima decennale sul tuo dispositivo — indicativa per la pianificazione stagionale." },
        "يحلّل توجه الأشهر القادمة…": { en: "Analyzing the months-ahead trend…", fr: "Analyse de la tendance des mois à venir…", de: "Trend der kommenden Monate wird analysiert…", es: "Analizando la tendencia de los próximos meses…", pt: "A analisar a tendência dos próximos meses…", it: "Analisi della tendenza dei prossimi mesi…" },
