        "ملابس متوسطة مريحة": { en: "Comfortable mid-layer clothing", fr: "Tenue intermédiaire confortable", de: "Angenehme Übergangskleidung", es: "Ropa media cómoda", pt: "Roupas intermediárias confortáveis", it: "Abbigliamento medio confortevole" },
