        "رياضيون، بحر، درونز وطائرات مسيرة، وصحة": { en: "Sports, sea, drones & health", fr: "Sport, mer, drones et santé", de: "Sport, Meer, Drohnen & Gesundheit", es: "Deporte, mar, drones y salud", pt: "Desporto, mar, drones e saúde", it: "Sport, mare, droni e salute" },
        "طقس مصمّم لنشاطك تحديدًا": { en: "Weather tailored to your activity", fr: "Un temps taillé pour votre activité", de: "Wetter, zugeschnitten auf deine Aktivität", es: "Tiempo a medida para tu actividad", pt: "Tempo à medida da sua atividade", it: "Meteo su misura per la tua attività" },
        "لوحة طقس للرياضيين ومرتادي البحر ومشغلي الدرونز والطائرات المسيرة ومرضى الحساسية — أرقام عملية بالساعة من موقعك.": { en: "Weather tailored specifically to your active lifestyle.", fr: "Un tableau météo pour sportifs, marins, pilotes de drones et allergiques — des chiffres horaires pratiques pour votre position.", de: "Ein Aktivitätsbrett für Sportler, Wasserratten, Drohnenpiloten und Allergiker — praktische Stundenzahlen für deinen Ort.", es: "Un panel para deportistas, bañistas, pilotos de drones y alérgicos — cifras horarias prácticas de tu ubicación.", pt: "Um painel para desportistas, banhistas, pilotos de drones e alérgicos — números horários práticos do teu local.", it: "Un cruscotto per sportivi, bagnanti, piloti di droni e allergici — numeri orari pratici della tua posizione." },
        "نجمع أرقام نشاطك…": { en: "Gathering your activity numbers…", fr: "Collecte de vos chiffres d'activité…", de: "Wir sammeln deine Aktivitätszahlen…", es: "Recopilando tus cifras de actividad…", pt: "A recolher os teus números de atividade…", it: "Raccogliamo i numeri della tua attività…" },
        "تعذّر تجهيز لوحة جوّك": { en: "Couldn't prepare the activity board", fr: "Impossible de préparer le tableau d'activités", de: "Aktivitätsbrett konnte nicht vorbereitet werden", es: "No se pudo preparar el panel de actividades", pt: "Não foi possível preparar o painel de atividades", it: "Impossibile preparare il cruscotto attività" },
        "افتح لوحة القيادة أولًا لتجهيز بيانات الطقس ثم عد إلى هذه الصفحة.": { en: "Open the dashboard first to load weather data, then come back to this page.", fr: "Ouvrez d'abord le tableau de bord pour charger les données, puis revenez.", de: "Öffne zuerst die Übersicht, damit Wetterdaten geladen werden, und komm dann zurück.", es: "Abre primero el panel para cargar los datos del tiempo y vuelve a esta página.", pt: "Abre primeiro o painel para carregar os dados do tempo e volta a esta página.", it: "Apri prima il cruscotto per caricare i dati meteo, poi torna a questa pagina." },
        "طقس الرياضيين والأنشطة الخارجية": { en: "Sports & outdoor activities weather", fr: "Météo des sportifs et activités outdoor", de: "Wetter für Sport & Outdoor", es: "Meteo para deportes y actividades al aire libre", pt: "Meteo para desporto e ar livre", it: "Meteo sport e attività all'aperto" },
        "أفضل ساعات التمرين · الإجهاد الحراري · الرياح للدراجين": { en: "Best workout hours · heat stress · cyclist winds", fr: "Meilleures heures d'entraînement · stress thermique · vents cyclistes", de: "Beste Trainingsstunden · Hitzestress · Wind für Radfahrer", es: "Mejores horas de entreno · estrés térmico · viento para ciclistas", pt: "Melhores horas de treino · stress térmico · vento para ciclistas", it: "Migliori ore di allenamento · stress termico · vento per ciclisti" },
        "رياضة": { en: "Sports", fr: "Sport", de: "Sport", es: "Deporte", pt: "Desporto", it: "Sport" },
        "أفضل الساعات للتمرين اليوم": { en: "Best hours to train today", fr: "Meilleures heures pour s'entraîner aujourd'hui", de: "Beste Stunden zum Training heute", es: "Mejores horas para entrenar hoy", pt: "Melhores horas para treinar hoje", it: "Migliori ore per allenarsi oggi" },
        "الدرجة تجمع الحرارة والرطوبة وسرعة الرياح واقتراب المطر — كلما اقتربت من 100 كان التوقيت مثاليًا للجهد العالي.": { en: "The score blends temperature, humidity, wind and incoming rain — the closer to 100, the better the window for intense effort.", fr: "Le score mêle température, humidité, vent et pluie attendue — plus proche de 100, meilleure est la fenêtre.", de: "Der Score mischt Temperatur, Luftfeuchte, Wind und nahenden Regen — je näher an 100, desto besser das Fenster für intensive Anstrengung.", es: "La puntuación mezcla temperatura, humedad, viento y lluvia cercana — cuanto más cerca de 100, mejor la ventana para el esfuerzo intenso.", pt: "A pontuação junta temperatura, humidade, vento e chuva próxima — quanto mais perto de 100, melhor a janela para esforço intenso.", it: "Il punteggio unisce temperatura, umidità, vento e pioggia in arrivo — più vicino a 100, migliore è la finestra per lo sforzo intenso." },
        "مقياس الرياح للدراجين": { en: "Cyclists' wind gauge", fr: "Jauge de vent pour cyclistes", de: "Windmesser für Radfahrer", es: "Medidor de viento para ciclistas", pt: "Medidor de vento para ciclistas", it: "Misuratore di vento per ciclisti" },
        "اختر اتجاه سيرك وستخبرك الرياح إن كانت مواجهة تُصعّب الدفع أو خلفية تدفعك أو جانبية تزيحك عن المسار.": { en: "Pick your riding direction — we'll tell you if the wind is a headwind that slows you, a tailwind that pushes you, or a crosswind that drifts you off line.", fr: "Choisissez votre direction : vent de face, vent arrière ou vent latéral.", de: "Wähle deine Fahrtrichtung — der Wind verrät dir, ob er von vorn bremst, von hinten schiebt oder seitlich drückt.", es: "Elige tu dirección — el viento te dirá si es de frente y frena, de cola y empuja, o lateral y desvía.", pt: "Escolhe a tua direção — o vento diz-te se é de frente e trava, de trás e empurra, ou lateral e desvia.", it: "Scegli la tua direzione — il vento ti dirà se è frontale e frena, da dietro e spinge, o laterale e sposta." },
        "اتجاه سيرك": { en: "Your riding direction", fr: "Votre direction", de: "Deine Fahrtrichtung", es: "Tu dirección", pt: "A tua direção", it: "La tua direzione" },
