        "إخفاء اللوحات المتقدمة": { en: "Hide advanced palettes", fr: "Masquer les palettes avancées", de: "Erweiterte Paletten ausblenden", es: "Ocultar paletas avanzadas", pt: "Ocultar paletas avançadas", it: "Nascondi le palette avanzate" },
        "البحث عن موقع": { en: "Search for a location", fr: "Rechercher un lieu", de: "Nach einem Ort suchen", es: "Buscar una ubicación", pt: "Pesquisar um local", it: "Cerca una posizione" },
        "قائمة الطبقات": { en: "Layers menu", fr: "Menu des couches", de: "Ebenenmenü", es: "Menú de capas", pt: "Menu de camadas", it: "Menu dei livelli" },
