        "جنوب غرب": { en: "Southwest", fr: "Sud-ouest", de: "Südwest", es: "Suroeste", pt: "Sudoeste", it: "Sud-ovest" },
        "غرب": { en: "West", fr: "Ouest", de: "West", es: "Oeste", pt: "Oeste", it: "Ovest" },
        "شمال غرب": { en: "Northwest", fr: "Nord-ouest", de: "Nordwest", es: "Noroeste", pt: "Noroeste", it: "Nord-ovest" },
