        "حرارة {p} السنوية شبه ثابتة عبر هذه السنين.": { en: "{p}'s yearly temperature has been nearly stable across these years.", fr: "La température annuelle de {p} est restée quasi stable sur ces années.", de: "Die Jahrestemperatur von {p} blieb über diese Jahre nahezu stabil.", es: "La temperatura anual de {p} se ha mantenido casi estable estos años.", pt: "A temperatura anual de {p} manteve-se quase estável nestes anos.", it: "La temperatura annuale di {p} è rimasta quasi stabile in questi anni." },
        "أمطار السنة تتراجع: نحو <b>{v}٪</b> كل عشر سنوات.": { en: "Yearly rain is shrinking: about <b>{v}%</b> per decade.", fr: "La pluie annuelle recule : environ <b>{v} %</b> par décennie.", de: "Der Jahresregen schrumpft: etwa <b>{v} %</b> pro Jahrzehnt.", es: "La lluvia anual retrocede: unos <b>{v}%</b> por década.", pt: "A chuva anual recua: cerca de <b>{v}%</b> por década.", it: "La pioggia annuale arretra: circa <b>{v}%</b> per decennio." },
        "أمطار السنة في زيادة: نحو <b>{v}٪</b> كل عشر سنوات.": { en: "Yearly rain is growing: about <b>{v}%</b> per decade.", fr: "La pluie annuelle augmente : environ <b>{v} %</b> par décennie.", de: "Der Jahresregen nimmt zu: etwa <b>{v} %</b> pro Jahrzehnt.", es: "La lluvia anual aumenta: unos <b>{v}%</b> por década.", pt: "A chuva anual aumenta: cerca de <b>{v}%</b> por década.", it: "La pioggia annuale aumenta: circa <b>{v}%</b> per decennio." },
        "هذا اليوم تحديدًا يزداد حرارة مع السنين: نحو <b>{v}°</b> كل عشر سنوات.": { en: "This very day is warming with the years: about <b>{v}°</b> per decade.", fr: "Ce jour précis se réchauffe au fil des ans : environ <b>{v}°</b> par décennie.", de: "Genau dieser Tag wird mit den Jahren wärmer: etwa <b>{v}°</b> pro Jahrzehnt.", es: "Este mismo día se calienta con los años: unos <b>{v}°</b> por década.", pt: "Este mesmo dia aquece com os anos: cerca de <b>{v}°</b> por década.", it: "Proprio questo giorno si scalda con gli anni: circa <b>{v}°</b> per decennio." },
